      const keys=x.effects.map(e=>e.key);
      if(new Set(keys).size!==3||keys.some(k=>!BOSS_EFFECT_KEYS.has(k)))throw Error('BOSS 專屬詞綴三條屬性必須有效且互不重複：'+x.id);
