  const h=[...heroes()].sort((a,b)=>a.lv-b.lv)[0],mi=row.mapIndex,mode=party.difficulty||0;
  foes=[];effects=[];actorCooldowns={};supportCooldowns={};round=0;for(const hero of heroes())hero.shield=0;
